def control(o):
 h=o['hitch_deg']; cam=o['views'].get('camera'); des=0
 if cam:
  sides=[[],[]]
  for b,d in cam['walls']:
   a=math.radians(b+h); u=-d*math.cos(a); y=d*math.sin(a)
   if 0.8<u<6.5: sides[0 if y<0 else 1].append((u,y))
  mids=[]
  for u,y in sides[0]:
   if sides[1]:
    z=min(sides[1],key=lambda p:abs(p[0]-u))
    if abs(z[0]-u)<0.65: mids.append(((u+z[0])/2,(y+z[1])/2))
  if mids:
   p=min(mids,key=lambda p:abs(p[0]-3.7)); des=math.degrees(math.atan2(5.2*p[1],max(4,p[0]**2)))
 des=max(-30,min(30,des))
 steer=max(-34,min(34,0.75*h+1.8*(h-des)))
 return steer,-0.7,-23

