import math
def control(obs):
    h=obs['hitch_deg']; r=math.radians(h)
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
            s=-math.cos(r)*x+math.sin(r)*y
            z=math.sin(r)*x+math.cos(r)*y
            if 2<s<12 and abs(z)>1.5:
                sides[0 if z>0 else 1].append((s,z))
        if all(sides):
            vals=[]
            for pts in sides:
                pts=sorted(pts,key=lambda p:abs(p[0]-7))[:3]
                vals.append(sum(p[1] for p in pts)/len(pts))
            offset=sum(vals)/2
            desired=math.degrees(math.atan(10.2*2*offset/(49+offset*offset)))
            desired=max(-32,min(32,desired))
    steer=2.0*(h-desired)+math.degrees(math.atan(3.9/10.2*math.sin(r)))
    return (max(-42,min(42,steer)), -0.9, -41)

